package savesystem;

import java.io.IOException;

/**
 * Thrown when a game save file is incomplete or is of an invalid format.
 * 
 * This exception is raised during save file parsing when required fields
 * are missing, block structures are invalid, or index values are invalid.
 * 
 * @author Tyler Ohme
 */
public class InvalidSaveFileException extends IOException {
	// Serial UID generated by Eclipse IDE.
	private static final long serialVersionUID = 7087803666443201619L;
	
	/**
	 * Creates a new InvalidSaveFileException with the given error message.
	 * 
	 * @param message a descsription of what caused the exception to be raised
	 * Author: Tyler Ohme
	 */
	public InvalidSaveFileException(String message) {
		super(message);
	}
}
